<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_auth();
$user=current_user(); $error=null; $edit=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$supplier=isset($_POST['is_supplier'])?1:0;$buyer=isset($_POST['is_buyer'])?1:0;$notes=trim($_POST['notes']??'');if(strlen($name)<2||(!$supplier&&!$buyer))$error='Informe o nome e escolha pelo menos um papel.';else{$values=[$name,$email?:null,$phone?:null,$supplier,$buyer,$notes];if($id){$sql='UPDATE contacts SET name=?,email=?,phone=?,is_supplier=?,is_buyer=?,notes=? WHERE id=? AND user_id=?';$values=[...$values,$id,$user['id']];}else{$sql='INSERT INTO contacts (name,email,phone,is_supplier,is_buyer,notes,user_id) VALUES (?,?,?,?,?,?,?)';$values[]=$user['id'];}db()->prepare($sql)->execute($values);flash('success','Contato salvo.');redirect('contacts.php');}}
if(isset($_GET['delete'])){db()->prepare('DELETE FROM contacts WHERE id=? AND user_id=?')->execute([(int)$_GET['delete'],$user['id']]);flash('success','Contato removido.');redirect('contacts.php');}
$editing=null;if($edit){$q=db()->prepare('SELECT * FROM contacts WHERE id=? AND user_id=?');$q->execute([$edit,$user['id']]);$editing=$q->fetch();}$q=db()->prepare('SELECT * FROM contacts WHERE user_id=? ORDER BY name');$q->execute([$user['id']]);$contacts=$q->fetchAll();$pageTitle='Contatos recorrentes';require __DIR__.'/partials/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="eyebrow">Relacionamento</div><h1 class="page-title h3 mb-0">Contatos recorrentes</h1></div></div><div class="row g-4"><div class="col-lg-5"><div class="panel"><h2 class="h5 mb-3"><?= $editing?'Editar contato':'Novo contato' ?></h2><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" data-validate novalidate><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= $editing['id']??'' ?>"><label class="form-label">Nome *</label><input class="form-control mb-3" name="name" required value="<?= e($editing['name']??'') ?>"><label class="form-label">E-mail</label><input class="form-control mb-3" type="email" name="email" value="<?= e($editing['email']??'') ?>"><label class="form-label">Telefone</label><input class="form-control mb-3" name="phone" value="<?= e($editing['phone']??'') ?>"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_supplier" id="supplier" <?= !empty($editing['is_supplier'])?'checked':'' ?>><label class="form-check-label" for="supplier">Fornece peças</label></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="is_buyer" id="buyer" <?= !empty($editing['is_buyer'])?'checked':'' ?>><label class="form-check-label" for="buyer">Compra peças</label></div><label class="form-label">Observações</label><textarea class="form-control mb-3" name="notes"><?= e($editing['notes']??'') ?></textarea><button class="btn btn-primary">Salvar contato</button><?php if($editing): ?> <a class="btn btn-outline-secondary" href="contacts.php">Cancelar</a><?php endif; ?></form></div></div><div class="col-lg-7"><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Contato</th><th>Papel</th><th>Ações</th></tr></thead><tbody><?php foreach($contacts as $contact): ?><tr><td><strong><?= e($contact['name']) ?></strong><div class="small text-muted"><?= e($contact['phone']??'') ?></div></td><td><?= $contact['is_supplier']?'Fornecedor':'' ?><?= $contact['is_supplier']&&$contact['is_buyer']?' · ':'' ?><?= $contact['is_buyer']?'Comprador':'' ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="contacts.php?id=<?= $contact['id'] ?>">Editar</a> <a class="btn btn-sm btn-outline-danger" data-confirm="Remover este contato?" href="contacts.php?delete=<?= $contact['id'] ?>">Excluir</a></td></tr><?php endforeach; if(!$contacts): ?><tr><td colspan="3" class="empty">Nenhum contato recorrente cadastrado.</td></tr><?php endif; ?></tbody></table></div></div></div></div><?php require __DIR__.'/partials/footer.php'; ?>
